// Shorthand for "plain noise" without any of the extra features
float noise(vec2 x) {
  vec2 g;
  return psrdnoise(x, vec2(0.0), 0.0, g);
}

// Shorthand for "periodic noise" without the other features
float pnoise(vec2 x, vec2 p) {
  vec2 g;
  return psrdnoise(x, p, 0.0, g);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    const float twoPI = 6.283185207;

    // uv coordinate range is [-1,1] along the shortest axis
    vec2 uv = 2.0*(fragCoord-iResolution.xy*0.5)/min(iResolution.x, iResolution.y);

    vec3 bgcolor = vec3(1.0); // White
    vec3 spotcolor = vec3(0.8,0.0,0.0); // Red

    float spot1 = aastep(0.3, distance(uv, vec2(-1.0, 0.0))); // Circular spot

    // Spatter, like a printed halftone dot
    float offset2 = mod(floor(iTime)*1.337, 143.0);
    float r2 = distance(uv, vec2(0.0, 0.0));
    float n2 = noise(12.0*uv + offset2);
    n2 += 0.5 * noise(24.0*uv + offset2);
    float spot2 = aastep(0.3, r2 + 0.1*n2);

    // Splotch, like a large splash of paint
    float offset3 = mod(floor(iTime+0.5)*1.337, 143.0);
    float angle3 = atan(uv.x-1.0, uv.y)/twoPI; // Scale angle to [0,1]
    float r3 = distance(uv, vec2(1.0, 0.0));
    float n3a = pnoise(vec2(r3*5.0+offset3, angle3*32.0), vec2(0.0, 32.0));
    n3a *= smoothstep(0.1,0.15, r3);
    float n3b = n3a + 0.5*pnoise(vec2(r3*10.0+offset3, angle3*64.0), vec2(0.0, 64.0));
    n3b *= smoothstep(0.1,0.15, r3);
    float n3 = n3a - 2.0*n3b*n3b;
    float spot3 = aastep(0.3, r3 + 0.1*n3);

    float spots = min(min(spot1, spot2), spot3);

    //vec3 col = mix(spotcolor, bgcolor, n3b);
    vec3 col = mix(spotcolor, bgcolor, spots);

    fragColor = vec4(col, 1.0);
}

float aastep(float a, float x) {
    float w = 0.7*fwidth(x-a);
    return smoothstep(-w, w, x-a);
}

// psrdnoise (c) Stefan Gustavson and Ian McEwan,
// ver. 2021-12-02, published under the MIT license:
// https://github.com/stegu/psrdnoise/
float psrdnoise(vec2 x, vec2 period, float alpha, out vec2 gradient)
{
	vec2 uv = vec2(x.x+x.y*0.5, x.y);
	vec2 i0 = floor(uv), f0 = fract(uv);
	float cmp = step(f0.y, f0.x);
	vec2 o1 = vec2(cmp, 1.0-cmp);
	vec2 i1 = i0 + o1, i2 = i0 + 1.0;
	vec2 v0 = vec2(i0.x - i0.y*0.5, i0.y);
	vec2 v1 = vec2(v0.x + o1.x - o1.y*0.5, v0.y + o1.y);
	vec2 v2 = vec2(v0.x + 0.5, v0.y + 1.0);
	vec2 x0 = x - v0, x1 = x - v1, x2 = x - v2;
	vec3 iu, iv, xw, yw;
	if(any(greaterThan(period, vec2(0.0)))) {
		xw = vec3(v0.x, v1.x, v2.x);
		yw = vec3(v0.y, v1.y, v2.y);
		if(period.x > 0.0)
			xw = mod(vec3(v0.x, v1.x, v2.x), period.x);
		if(period.y > 0.0)
			yw = mod(vec3(v0.y, v1.y, v2.y), period.y);
		iu = floor(xw + 0.5*yw + 0.5); iv = floor(yw + 0.5);
	} else {
		iu = vec3(i0.x, i1.x, i2.x); iv = vec3(i0.y, i1.y, i2.y);
	}
	vec3 hash = mod(iu, 289.0);
	hash = mod((hash*51.0 + 2.0)*hash + iv, 289.0);
	hash = mod((hash*34.0 + 10.0)*hash, 289.0);
	vec3 psi = hash*0.07482 + alpha;
	vec3 gx = cos(psi); vec3 gy = sin(psi);
	vec2 g0 = vec2(gx.x, gy.x);
	vec2 g1 = vec2(gx.y, gy.y);
	vec2 g2 = vec2(gx.z, gy.z);
	vec3 w = 0.8 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2));
	w = max(w, 0.0); vec3 w2 = w*w; vec3 w4 = w2*w2;
	vec3 gdotx = vec3(dot(g0, x0), dot(g1, x1), dot(g2, x2));
	float n = dot(w4, gdotx);
	vec3 w3 = w2*w; vec3 dw = -8.0*w3*gdotx;
	vec2 dn0 = w4.x*g0 + dw.x*x0;
	vec2 dn1 = w4.y*g1 + dw.y*x1;
	vec2 dn2 = w4.z*g2 + dw.z*x2;
	gradient = 10.9*(dn0 + dn1 + dn2);
	return 10.9*n;
}
